const message=s=>{el('#sharedToast').hidden=false;el('#sharedToast').textContent=s;clearTimeout(message.timer);message.timer=setTimeout(()=>el('#sharedToast').hidden=true,6000)};
function failure(e){const raw=e?.message||String(e);return /Conflict/.test(raw)?'این کار توسط فرد دیگری به‌روز شده. تازه‌سازی کنید و دوباره اقدام کنید.':/Access denied|Cannot|protected|Only/.test(raw)?'دسترسی این تغییر را ندارید یا وضعیت کار تغییر کرده است.':/Email rate limit/.test(raw)?'محدودیت ارسال ایمیل؛ کمی بعد دوباره تلاش کنید.':/Invalid login|expired|invalid.*token/i.test(raw)?'کد یا لینک ورود معتبر نیست یا منقضی شده است.':/Failed to fetch|NetworkError/.test(raw)?'ارتباط برقرار نشد؛ اتصال اینترنت را بررسی کنید.':raw}
async function checked(p){const r=await p;if(r.error)throw r.error;return r.data}
async function rpc(name,args={}){return checked(db.rpc(name,args))}
async function refresh(){if(!project)return;const [ts,ms,ns,trashRows]=await Promise.all([checked(db.from('sm_tasks').select('*').eq('project_id',project.id).order('updated_at',{ascending:false})),checked(db.from('sm_members').select('*').eq('project_id',project.id).order('name')),checked(db.from('sm_notices').select('*').eq('project_id',project.id).order('created_at',{ascending:false}).limit(100)),checked(db.from('sm_task_trash').select('task_id').eq('project_id',project.id))]);const removed=new Set(trashRows.map(x=>x.task_id));sharedDeleted=ts.filter(t=>removed.has(t.id));tasks=ts.filter(t=>!removed.has(t.id));members=ms;notices=ns;if(!mine()){project=null;throw Error('عضویت شما غیرفعال شده است.')}render()}
let passwordSetup=false;
async function passwordForm(){
 clearInterval(poll);
 el('#sharedApp').innerHTML='<section class="login-card"><h2>تعیین رمز شخصی</h2><p>رمزی با حداقل ۱۲ کاراکتر انتخاب کنید.</p><form id="newPasswordForm"><label>رمز جدید<input type="password" name="password" autocomplete="new-password" minlength="12" maxlength="128" required></label><label>تکرار رمز<input type="password" name="confirm" autocomplete="new-password" minlength="12" maxlength="128" required></label><button class="primary">ذخیره رمز و ورود</button><button type="button" class="secondary" id="cancelPassword">انصراف</button></form></section>';
 el('#cancelPassword').onclick=()=>{passwordSetup=false;loadAccount(session)};
 el('#newPasswordForm').onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button');if(f.password.value!==f.confirm.value)return message('تکرار رمز مطابقت ندارد.');b.disabled=true;try{await checked(db.auth.updateUser({password:f.password.value}));f.reset();passwordSetup=false;message('رمز شخصی ذخیره شد.');await loadAccount(session)}catch(err){message(failure(err))}finally{b.disabled=false}};
}
function authForm(note=''){el('#projectSelect').innerHTML='';el('#accountTools').innerHTML='<a href="index.html" class="demo-link">مشاهده نمونه آزمایشی</a>';el('#sharedApp').innerHTML=`<section class="login-card"><h2>ورود اعضای سمندیس</h2><p>با ایمیلی وارد شوید که برای شما در پروژه ثبت شده است. انتخاب نقش آزمایشی در این بخش وجود ندارد.</p>${note?`<div class="shared-error">${esc(note)}</div>`:''}<div class="shared-actions" aria-label="روش ورود"><button type="button" class="primary" id="otpMode" aria-pressed="true">کد ایمیلی</button><button type="button" class="secondary" id="passwordMode" aria-pressed="false">رمز عبور</button></div><form id="loginForm"><label>ایمیل<input type="email" name="email" dir="ltr" autocomplete="email" required maxlength="254"></label><label id="passwordLabel" hidden>رمز شخصی<input type="password" name="password" autocomplete="current-password" maxlength="128" disabled></label><button class="primary" id="loginSubmit">دریافت کد ورود</button><button type="button" class="text-btn" id="setupPassword">تعیین / فراموشی رمز</button></form><p class="shared-meta">ورود شما در این مرورگر حفظ می‌شود؛ در دستگاه عمومی پس از استفاده خارج شوید.</p><form id="verifyForm" hidden><p>کد یک‌بارمصرف ارسال‌شده به ایمیل‌تان را اینجا وارد کنید.</p><label>کد ورود<input name="code" inputmode="numeric" dir="ltr" autocomplete="one-time-code" minlength="6" maxlength="8" required></label><button class="primary">ورود با کد</button></form><p class="shared-meta">ایجاد حساب به‌تنهایی اجازهٔ مشاهدهٔ پروژه را نمی‌دهد؛ عضویت باید قبلاً توسط مدیریت ثبت شده باشد.</p></section>`;let mode='otp';passwordSetup=false;
const choose=m=>{mode=m;passwordSetup=false;el('#passwordLabel').hidden=m!=='password';el('#loginForm').password.disabled=m!=='password';el('#loginForm').password.required=m==='password';el('#loginSubmit').textContent=m==='password'?'ورود با رمز':'دریافت کد ورود';el('#verifyForm').hidden=true;for(const [id,v]of [['otpMode','otp'],['passwordMode','password']]){el('#'+id).className=m===v?'primary':'secondary';el('#'+id).setAttribute('aria-pressed',String(m===v))}};
el('#otpMode').onclick=()=>choose('otp');el('#passwordMode').onclick=()=>choose('password');
el('#setupPassword').onclick=()=>{choose('otp');if(!el('#loginForm').email.reportValidity())return;passwordSetup=true;el('#loginForm').requestSubmit()};
el('#loginForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const email=e.target.email.value.trim().toLowerCase();if(mode==='password'){await checked(db.auth.signInWithPassword({email,password:e.target.password.value}));e.target.password.value='';return;}await checked(db.auth.signInWithOtp({email,options:{emailRedirectTo:location.origin+'/shared.html'}}));el('#verifyForm').hidden=false;el('#verifyForm').dataset.email=email;message('کد ورود ارسال شد؛ پوشه اسپم را هم بررسی کنید.')}catch(err){message(failure(err))}finally{b.disabled=false}};el('#verifyForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const result=await checked(db.auth.verifyOtp({email:e.target.dataset.email,token:e.target.code.value.trim().replace(/[۰-۹]/g,c=>String('۰۱۲۳۴۵۶۷۸۹'.indexOf(c))).replace(/[٠-٩]/g,c=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(c))),type:'email'}));e.target.code.value='';if(passwordSetup){session=result.session;await passwordForm()}}catch(err){message(failure(err))}finally{b.disabled=false}};}
async function loadAccount(s){const gen=++authGeneration;clearInterval(poll);session=s;project=null;tasks=[];members=[];notices=[];el('#sharedDialog').close();if(!s){authForm();return}el('#sharedApp').innerHTML='<div class="shared-message">در حال دریافت پروژه‌های شما…</div>';try{await rpc('sm_claim_membership');const ps=await checked(db.from('sm_projects').select('*').order('created_at'));if(gen!==authGeneration)return;projects=ps;if(!ps.length){el('#accountTools').innerHTML=`<span class="shared-user" dir="ltr">${esc(s.user.email)}</span><button id="signout" class="signout">خروج</button>`;el('#signout').onclick=()=>db.auth.signOut();el('#sharedApp').innerHTML='<div class="shared-message"><h2>عضویت شما هنوز به پروژه متصل نشده است</h2><p>ورود موفق بود؛ مدیریت باید همین ایمیل را در فهرست اعضای پروژه ثبت کند. داده‌های نمونهٔ مرورگر شما محفوظ‌اند.</p><button class="secondary" id="retryMembership">بررسی دوباره عضویت</button> <a href="index.html">نمونه آزمایشی</a></div>';el('#retryMembership').onclick=()=>loadAccount(session);return}project=ps[0];await refresh();if(gen!==authGeneration)return;poll=setInterval(()=>{if(document.visibilityState==='visible'&&!busy)refresh().catch(e=>message(failure(e)))},20000)}catch(e){authForm('اتصال به فضای مشترک کامل نشد: '+failure(e))}}
function render(){if(!project||!mine())return;el('#sharedProjectTitle').textContent=project.name;el('#projectSelect').innerHTML=`<select aria-label="پروژه جاری" id="chooseProject">${projects.map(p=>`<option value="${p.id}" ${p.id===project.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select>`;el('#chooseProject').onchange=async e=>{project=projects.find(p=>p.id===e.target.value);selectedTask=null;scope='mine';el('#sharedDialog').close();await refresh()};el('#accountTools').innerHTML=`<span class="shared-user">${esc(mine().name)}<small>${esc(mine().title)}</small></span><button class="notice-inbox-button" id="sharedBell" aria-label="اعلان‌های خوانده‌نشده">اعلان‌ها ${fa(notices.filter(n=>!n.read).length)}</button><button class="signout" id="signout">خروج</button>`;el('#signout').onclick=()=>db.auth.signOut();el('#sharedBell').onclick=showNotices;const myTasks=tasks.filter(t=>own(t)||collaborating(t));el('#sharedApp').innerHTML=`<nav class="shared-nav">${[['mine','کارهای من '+fa(myTasks.length)],['all','همه کارها '+fa(tasks.length)],['program','برنامه پروژه'],...(management()?[['members','اعضا'],['reports','گزارش افراد']]:[])].map(([v,l])=>`<button data-scope="${v}" class="${scope===v?'active':''}">${l}</button>`).join('')}<button id="createTask" class="primary">＋ کار جدید</button></nav><div class="shared-banner">فضای مشترک · ذخیره در دیتابیس · آخرین دریافت: ${new Date().toLocaleTimeString('fa-IR',{hour:'2-digit',minute:'2-digit'})} <button class="text-btn" id="refreshShared">تازه‌سازی</button></div><div id="sharedContent"></div>`;document.querySelectorAll('[data-scope]').forEach(b=>b.onclick=()=>{scope=b.dataset.scope;phase='all';search='';render()});el('#refreshShared').onclick=()=>refresh().catch(e=>message(failure(e)));el('#createTask').onclick=createTaskForm;if(scope==='members')renderMembers();else if(scope==='reports')renderReports();else if(scope==='program')renderProgram();else renderTasks();}
function renderTasks(){const list=tasks.filter(t=>(scope==='all'||own(t)||collaborating(t))&&(phase==='all'||t.status===phase)&&(t.title+' '+t.description).includes(search));el('#sharedContent').innerHTML=`<div class="shared-subtools"><div class="shared-filter">${[['all','همه'],...Object.entries(labels)].map(([v,l])=>`<button data-filter="${v}" class="${phase===v?'active':''}">${l}</button>`).join('')}</div><input id="sharedSearch" aria-label="جست‌وجوی کار" placeholder="جست‌وجوی کار…" value="${esc(search)}"></div>${list.length?`<div class="clarity-list"><div class="clarity-table"><table><thead><tr><th>کار</th><th>مسئول</th><th>مهلت</th><th>وضعیت</th></tr></thead><tbody>${list.map(t=>`<tr><td><div class="shared-task-line"><button class="task-tick ${t.status}" data-complete="${t.id}" aria-label="${t.status==='open'?'انجام شد: ':'بازگشایی: '}${esc(t.title)}" role="checkbox" aria-checked="${t.status!=='open'}" ${t.status==='done'?!reviewer(t)?'disabled':'':!own(t)&&!canManage(t)?'disabled':''}>${t.status==='open'?'':'✓'}</button><button class="shared-task-title" data-task="${t.id}">${esc(t.title)}${t.collaborators.length?`<small class="task-collaborator-names">همکاران: ${t.collaborators.map(person).map(esc).join('، ')}</small>`:''}${collaborating(t)&&!own(t)?'<small>با همکاری شما</small>':''}</button></div></td><td>${esc(person(t.owner_id))}</td><td>${date(t.due)}</td><td><span class="pill clarity-${t.status}">${labels[t.status]}</span>${contribute(t)&&t.status!=='done'?`<button class="row-upload" data-upload="${t.id}">↑ بارگذاری فایل</button>`:''}${reviewer(t)&&t.status==='review'?`<button class="approve-inline" data-approve="${t.id}">تأیید نهایی</button>`:''}</td></tr>`).join('')}</tbody></table></div></div>`:'<div class="shared-empty">کاری در این بخش نیست. کار جدید تعریف کنید یا «همه کارها» را ببینید.</div>'}`;el('#sharedSearch').oninput=e=>{const caret=e.target.selectionStart;search=e.target.value;renderTasks();el('#sharedSearch').focus();el('#sharedSearch').setSelectionRange(caret,caret)};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{phase=b.dataset.filter;renderTasks()});document.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>detail(b.dataset.task));document.querySelectorAll('[data-upload]').forEach(b=>b.onclick=()=>detail(b.dataset.upload,true));document.querySelectorAll('[data-complete]').forEach(b=>b.onclick=()=>{const t=tasks.find(t=>t.id===b.dataset.complete);action(t,t.status==='open'?'submit':'reopen')});document.querySelectorAll('[data-approve]').forEach(b=>b.onclick=()=>action(tasks.find(t=>t.id===b.dataset.approve),'approve'));}
async function action(t,kind,text='',extra={}){if(busy)return;busy=true;const d=el('#sharedDetail');d.classList.add('shared-loading');try{await rpc('sm_task_action',{p_task:t.id,p_revision:t.revision,p_action:kind,p_text:text,...extra});await refresh();message(kind==='submit'?'انجام کار ثبت شد؛ منتظر تأیید ارجاع‌دهنده.':'تغییر در دیتابیس ذخیره شد.');if(selectedTask===t.id&&el('#sharedDialog').open)await detail(t.id)}catch(e){message(failure(e));await refresh().catch(()=>{})}finally{busy=false;d.classList.remove('shared-loading')}}
function modal(html){el('#sharedDetail').innerHTML=html;if(!el('#sharedDialog').open)el('#sharedDialog').showModal();const close=el('#sharedClose');if(close)close.onclick=()=>{selectedTask=null;el('#sharedDialog').close()}}
