async function detail(id,upload=false){if(sharedDeleted.some(t=>t.id===id))return message('این کار حذف شده است؛ مدیریت می‌تواند آن را از حذف‌شده‌ها بازیابی کند.');selectedTask=id;try{const [t,files,events]=await Promise.all([checked(db.from('sm_tasks').select('*').eq('id',id).single()),checked(db.from('sm_files').select('*').eq('task_id',id).eq('ready',true).order('created_at',{ascending:false})),checked(db.from('sm_events').select('*').eq('task_id',id).order('created_at'))]);if(selectedTask!==id)return;const i=tasks.findIndex(x=>x.id===id);if(i>=0)tasks[i]=t;modal(`${modalHead(t.title)}<div class="shared-facts"><span>${labels[t.status]}</span><span>مسئول: ${esc(person(t.owner_id))}</span><span>تأیید با: ${esc(person(t.reviewer_id))}</span><span>مهلت: ${date(t.due)}</span><span>تعریف: ${date(t.created_at)}</span></div><p class="shared-description">${esc(t.description)}</p>${t.collaborators.length?`<p class="shared-meta">همکاران: ${t.collaborators.map(person).map(esc).join('، ')}</p>`:''}<div class="shared-actions">${canManage(t)&&t.status!=='done'?'<button class="secondary" id="editCollaborators">＋ انتخاب / ویرایش همکاران</button>':''}${t.status==='open'&&(own(t)||canManage(t))?'<button class="primary" id="submitTask">✓ انجام شد</button>':''}${t.status==='review'&&reviewer(t)?'<button class="primary" id="approveTask">تأیید نهایی</button>':''}${t.status==='review'&&(own(t)||canManage(t))||t.status==='done'&&reviewer(t)?'<button class="secondary" id="reopenTask">ادامه کار</button>':''}</div><p class="status-note">تیک انجام کار، آخرین فایل‌های ثبت‌شده را برای تأیید ارجاع‌دهنده می‌فرستد. تأیید و نسخه‌های قبلی در سوابق باقی می‌مانند.</p><section class="shared-section"><h3>فایل‌های کار</h3>${files.map(f=>`<div class="shared-attachment"><button data-file="${f.id}">↓ ${esc(f.name)}</button><small>${esc(f.label)} · ${esc(person(f.author_id))} · ${date(f.created_at)}${t.final_files.includes(f.id)?' · نسخه تأییدشده':''}${t.status==='review'&&t.submitted_files.includes(f.id)?' · ارسال‌شده برای تأیید':''}</small></div>`).join('')||'<p class="shared-meta">هنوز فایلی ثبت نشده است.</p>'}${contribute(t)&&t.status!=='done'?'<form id="sharedUpload" class="shared-upload"><label>افزودن فایل<input id="sharedFiles" type="file" multiple required></label><label>نام نسخه (اختیاری)<input name="label" maxlength="120" placeholder="مثلاً نقشه اصلاح‌شده"></label><p class="shared-meta">تا ۱۰ فایل؛ هر فایل حداکثر ۲۰ و مجموعاً ۵۰ مگابایت. فایل‌ها خصوصی و مشترک بین اعضای مجاز پروژه‌اند.</p><button class="primary">بارگذاری و ثبت فایل</button><p class="shared-meta" id="uploadProgress"></p></form>':''}</section><section class="shared-section"><h3>گزارش و بازخورد</h3>${events.filter(e=>['report','correct','request'].includes(e.kind)).map(e=>`<div class="shared-report"><strong>${esc(person(e.actor_id))} · ${e.kind==='request'?'درخواست':e.kind==='correct'?'درخواست اصلاح':member(e.actor_id)?.role==='member'?'گزارش':'بازخورد'}</strong><p>${esc(e.text)}</p><small>${date(e.created_at)}</small></div>`).join('')||'<p class="shared-meta">هنوز گزارشی ثبت نشده است.</p>'}${contribute(t)?`<form id="sharedReport"><label>گزارش / بازخورد<textarea name="text" rows="3" required maxlength="4000"></textarea></label><div class="shared-actions"><button class="primary">ثبت گزارش</button>${reviewer(t)&&t.status==='review'?'<button type="button" class="secondary" id="correctTask">درخواست اصلاح</button>':''}</div></form>`:''}</section>${canManage(t)&&t.status!=='done'?`<details open id="taskAssignment"><summary>ویرایش مسئول و همکاران</summary><form id="assignForm"><label>مسئول اصلی<select name="owner">${members.filter(m=>m.active&&(mine().role==='director'||m.role!=='director')).map(m=>`<option value="${m.id}" ${m.id===t.owner_id?'selected':''}>${esc(m.name)}${m.external?' · بدون پنل':''}</option>`).join('')}</select></label><fieldset><legend>همکاران</legend>${members.filter(m=>m.active&&(mine().role==='director'||m.role!=='director')).map(m=>`<label class="checkbox-choice"><input type="checkbox" name="collaborators" value="${m.id}" ${t.collaborators.includes(m.id)?'checked':''}>${esc(m.name)}</label>`).join('')}</fieldset><button class="secondary">ذخیره ارجاع</button></form></details>`:mine().role==='member'&&contribute(t)&&t.status!=='done'?'<details><summary>درخواست تغییر مسئول یا همکاری</summary><form id="requestForm"><label>پیشنهاد و دلیل<textarea name="reason" required maxlength="2000"></textarea></label><button class="secondary">ثبت درخواست برای مدیریت</button></form></details>':''}<details><summary>همه سوابق (${fa(events.length)})</summary>${events.map(e=>`<p class="shared-meta">${esc(person(e.actor_id))} · ${esc(eventLabels[e.kind]||'گزارش')} · ${date(e.created_at)}</p>`).join('')}</details>`);if(el('#editCollaborators'))el('#editCollaborators').onclick=()=>el('#taskAssignment').scrollIntoView({block:'start',behavior:'smooth'});if(el('#submitTask'))el('#submitTask').onclick=()=>action(t,'submit');if(el('#approveTask'))el('#approveTask').onclick=()=>action(t,'approve');if(el('#reopenTask'))el('#reopenTask').onclick=()=>action(t,'reopen');if(el('#sharedReport'))el('#sharedReport').onsubmit=e=>{e.preventDefault();action(t,'report',e.target.text.value.trim())};if(el('#correctTask'))el('#correctTask').onclick=()=>{const text=el('#sharedReport').text.value.trim();if(!text)return message('دلیل اصلاح را در متن بازخورد بنویسید.');action(t,'correct',text)};if(el('#assignForm'))el('#assignForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);action(t,'assign','',{p_owner:f.get('owner'),p_collaborators:f.getAll('collaborators')})};if(el('#requestForm'))el('#requestForm').onsubmit=e=>{e.preventDefault();action(t,'request',e.target.reason.value.trim())};document.querySelectorAll('[data-file]').forEach(b=>b.onclick=()=>download(files.find(f=>f.id===b.dataset.file)));if(el('#sharedUpload'))el('#sharedUpload').onsubmit=e=>uploadFiles(e,t);if(upload&&el('#sharedUpload'))el('#sharedUpload').scrollIntoView({block:'center',behavior:'smooth'})}catch(e){message(failure(e))}}
async function download(f){try{const blob=await checked(db.storage.from('samandis-files').download(f.object_path));const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=f.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}catch(e){message(failure(e))}}
async function uploadFiles(e,t){e.preventDefault();if(busy)return;const fs=Array.from(el('#sharedFiles').files);if(fs.length>10||fs.some(f=>!f.size||f.size>20*1048576)||fs.reduce((n,f)=>n+f.size,0)>50*1048576)return message('حداکثر ۱۰ فایل، هر فایل ۲۰ و مجموعاً ۵۰ مگابایت؛ فایل خالی قابل ثبت نیست.');busy=true;e.target.querySelector('button').disabled=true;const label=e.target.label.value;let completed=0;try{for(const file of fs){el('#uploadProgress').textContent='در حال بارگذاری '+file.name;const f=await rpc('sm_reserve_file',{p_task:t.id,p_revision:t.revision,p_name:file.name,p_size:file.size,p_type:file.type||'application/octet-stream',p_label:label});await checked(db.storage.from('samandis-files').upload(f.object_path,file,{contentType:file.type||'application/octet-stream',upsert:false}));await rpc('sm_finalize_file',{p_file:f.id});completed++;t=await checked(db.from('sm_tasks').select('*').eq('id',t.id).single())}await refresh();await detail(t.id);message(fa(completed)+' فایل در فضای مشترک ذخیره شد.')}catch(err){message((completed?fa(completed)+' فایل ذخیره شد. ':'')+failure(err));if(e.target.isConnected){e.target.querySelector('button').disabled=false;el('#uploadProgress').textContent='بارگذاری کامل نشد؛ فایل‌های موفق محفوظ‌اند.'}}finally{busy=false}}
function createTaskForm(){selectedTask=null;const me=mine(),active=members.filter(m=>m.active),owners=management()?active.filter(m=>me.role==='director'||m.role!=='director'):[me],reviewers=management()?[me]:active.filter(m=>['director','supervisor'].includes(m.role));modal(`${modalHead('کار جدید')}<form id="newSharedTask"><label>عنوان<input name="title" maxlength="200" required></label><label>شرح<textarea name="description" rows="3" maxlength="10000"></textarea></label><label>مسئول<select name="owner">${owners.map(m=>`<option value="${m.id}" ${m.id===me.id?'selected':''}>${esc(m.name)}${m.external?' · بدون پنل':''}</option>`).join('')}</select></label>${management()?`<fieldset><legend>همکاران (اختیاری)</legend><p class="shared-meta">می‌توانید چند همکار انتخاب کنید؛ مسئول اصلی جداگانه مشخص می‌شود.</p>${owners.map(m=>`<label class="checkbox-choice"><input type="checkbox" name="collaborators" value="${m.id}">${esc(m.name)}</label>`).join('')}</fieldset>`:''}<label>بررسی‌کننده نهایی<select name="reviewer">${reviewers.map(m=>`<option value="${m.id}">${esc(m.name)}${m.external?' · بدون پنل':''}</option>`).join('')}</select></label><label>مهلت<input type="date" name="due"></label><button class="primary">ثبت کار</button></form>`);el('#newSharedTask').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;const f=new FormData(e.target);try{const id=await rpc('sm_create_task',{p_project:project.id,p_title:f.get('title'),p_description:f.get('description'),p_owner:f.get('owner'),p_reviewer:f.get('reviewer'),p_due:f.get('due')||null});const collaborators=f.getAll('collaborators').filter(x=>x!==f.get('owner'));let assignmentError=null;if(collaborators.length){try{await rpc('sm_task_action',{p_task:id,p_revision:0,p_action:'assign',p_owner:f.get('owner'),p_collaborators:collaborators})}catch(err){assignmentError=err;e.target.dataset.assignmentFailed='true'}}el('#sharedDialog').close();scope='mine';await refresh();await detail(id);message(assignmentError?'کار ساخته شد، اما همکاران ذخیره نشدند. از «ویرایش همکاران» دوباره انتخاب کنید؛ کار جدید نسازید.':'کار و همکاران در فضای مشترک ثبت شدند.')}catch(err){message(failure(err))}finally{busy=false}}}
function renderProgram(){const dated=tasks.filter(t=>t.due).sort((a,b)=>a.due.localeCompare(b.due));el('#sharedContent').innerHTML='<h2>تقویم تحویل کارها</h2>'+dated.map(t=>`<div class="shared-member"><div><b>${date(t.due)}</b><small>${esc(person(t.owner_id))} · ${labels[t.status]}</small></div><button class="text-btn" data-program-task="${t.id}">${esc(t.title)}</button></div>`).join('')+(dated.length?'':'<div class="shared-empty">هنوز موعدی ثبت نشده است.</div>');document.querySelectorAll('[data-program-task]').forEach(b=>b.onclick=()=>detail(b.dataset.programTask))}
function renderMembers(){if(!management())return;el('#sharedContent').innerHTML='<div class="shared-subtools"><h2>اعضای پروژه</h2><button class="secondary" id="addMember">＋ افزودن عضو</button></div><p class="shared-meta">ثبت ایمیل به عضو اجازهٔ ورود به این پروژه را می‌دهد؛ دعوت‌نامه خودکار ارسال نمی‌شود. فرد با همان ایمیل وارد می‌شود.</p><div class="shared-members">'+members.map(m=>`<div class="shared-member"><div><b>${esc(m.name)}</b><small>${esc(m.title)} · ${m.active?'فعال':'غیرفعال'} · ${m.external?'بدون پنل':m.user_id?'حساب متصل':'هنوز وارد نشده'}</small><small dir="ltr">${esc(m.email||'ایمیل تعیین نشده')}</small></div>${mine().role==='director'||m.role!=='director'?`<button class="text-btn" data-member="${m.id}">ویرایش</button>`:''}</div>`).join('')+'</div>';el('#addMember').onclick=()=>memberForm();document.querySelectorAll('[data-member]').forEach(b=>b.onclick=()=>memberForm(member(b.dataset.member)))}
function memberForm(m=null){selectedTask=null;modal(`${modalHead(m?'ویرایش عضو':'افزودن عضو')}<form id="memberEdit"><label>نام<input name="name" required maxlength="100" value="${esc(m?.name||'')}"></label><label>سمت<input name="title" required maxlength="100" value="${esc(m?.title||'')}"></label><label>ایمیل ورود<input name="email" type="email" dir="ltr" value="${esc(m?.email||'')}" ${m?.user_id?'readonly':''}></label><label>دسترسی<select name="role">${[['member','کارشناس'],['supervisor','سرپرست'],...(mine().role==='director'?[['director','مدیر پروژه']]:[])].map(([v,l])=>`<option value="${v}" ${m?.role===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="checkbox-choice"><input name="active" type="checkbox" ${m?.active!==false?'checked':''}>فعال</label><button class="primary">ذخیره عضو</button></form>`);el('#memberEdit').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;const f=new FormData(e.target);try{await rpc('sm_save_member',{p_project:project.id,p_id:m?.id||null,p_name:f.get('name'),p_title:f.get('title'),p_email:f.get('email'),p_role:f.get('role'),p_active:f.has('active')});el('#sharedDialog').close();await refresh();message('عضو ذخیره شد.')}catch(err){message(failure(err))}finally{busy=false}}}
function renderReports(){if(!management())return;el('#sharedContent').innerHTML='<h2>وضعیت کارهای اعضا</h2><p class="shared-meta">درصد زیر سهم کارهای تأییدشده از کل کارهای محول‌شده است؛ سنجش قطعی بازدهی فرد نیست.</p><div class="shared-members">'+members.filter(m=>mine().role==='director'||m.role!=='director').map(m=>{const own=tasks.filter(t=>t.owner_id===m.id),done=own.filter(t=>t.status==='done');return `<div class="shared-member"><div><b>${esc(m.name)}</b><small>${fa(own.length)} کار · ${fa(done.length)} تأییدشده</small></div><strong>${own.length?fa(Math.round(100*done.length/own.length))+'٪':'—'}</strong></div>`}).join('')+'</div>'}
function showNotices(){selectedTask=null;const unread=notices.filter(n=>!n.read);modal(modalHead('اعلان‌های شما')+'<p class="shared-meta">بعد از خواندن، تیک کنار اعلان را بزنید تا از این فهرست کنار برود.</p>'+unread.map(n=>`<div class="notice-inbox-row"><button type="button" class="notice-read-check" data-read-notice="${esc(n.id)}" aria-label="خوانده شد: ${esc(n.text)}" title="خوانده شد">✓</button><div><button type="button" class="notice-open" data-notice="${esc(n.id)}">${esc(n.text)}</button><small>${date(n.created_at)}</small></div></div>`).join('')+(unread.length?'':'<p class="shared-empty">اعلان خوانده‌نشده‌ای ندارید.</p>'));document.querySelectorAll('[data-notice]').forEach(b=>b.onclick=async()=>{const n=notices.find(n=>n.id===b.dataset.notice);if(n)await detail(n.task_id)});document.querySelectorAll('[data-read-notice]').forEach(b=>b.onclick=async()=>{if(b.disabled)return;b.disabled=true;try{await rpc('sm_read_notice',{p_notice:b.dataset.readNotice});await refresh();if(el('#sharedDialog').open&&el('[data-read-notice]'))showNotices()}catch(e){b.disabled=false;message(failure(e))}})}
el('#sharedDialog').addEventListener('cancel',()=>selectedTask=null);
db.auth.onAuthStateChange((event,s)=>{if(event==='SIGNED_OUT'){passwordSetup=false;setTimeout(()=>loadAccount(s),0)}else if(event==='SIGNED_IN'&&!passwordSetup){if(s?.user.id===session?.user.id&&project){session=s;return}setTimeout(()=>loadAccount(s),0)}else if(event==='TOKEN_REFRESHED'&&s?.user.id===session?.user.id){session=s}});
(async()=>{try{const {data,error}=await db.auth.getSession();if(error)throw error;if(data.session)await loadAccount(data.session);else authForm()}catch(e){authForm(failure(e))}})();
